package br.com.social;import br.com.social.auth.*;import br.com.social.post.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.Bean;import org.springframework.security.crypto.password.PasswordEncoder;@SpringBootApplication public class SocialApplication{public static void main(String[]a){SpringApplication.run(SocialApplication.class,a);}@Bean CommandLineRunner seed(AppUserRepository users,PostRepository posts,PasswordEncoder enc){return a->{if(users.findByEmail("admin@teste.com").isEmpty())users.save(new AppUser(null,"Moderador","admin@teste.com",enc.encode("123456"),Role.ADMIN));if(users.findByEmail("usuario@teste.com").isEmpty())users.save(new AppUser(null,"Francisco Demo","usuario@teste.com",enc.encode("123456"),Role.USER));if(posts.count()==0)posts.save(new Post("admin@teste.com","Moderador","Bem-vindo à rede social de exemplo. Crie posts, curta, comente e teste a moderação."));};}}